#!/bin/sh
# Real CLI checks for the installed unlzx.
#
# Run by test_package/conanfile.py as `sh test.sh <workdir>`.  The workdir
# already contains two LZX archives generated by the conanfile:
#
#   good.lzx  — one stored member "hello.txt" with correct header and data CRCs
#   bad.lzx   — the same archive with a deliberately corrupted header CRC
#
# All four assertions must hold; any failure exits non-zero, which makes
# conan's test() fail.
#
# POSIX sh only.  The extracted payload is checked by reading the file line by
# line with shell builtins rather than with cmp/diff, so the script does not
# depend on which utilities the worker image ships.
set -eu

workdir="${1:-.}"
cd "$workdir"

fail() {
    echo "FAIL: $1" >&2
    exit 1
}

MEMBER="hello.txt"
EXPECTED_LINE="unlzx round-trip payload 0123456789"

# 1. listing the archive must name the member.
unlzx -v good.lzx > view.log 2>&1
grep -q "$MEMBER" view.log || fail "unlzx -v did not list '$MEMBER': $(cat view.log)"
echo "ok   unlzx -v listed $MEMBER"

# 2. extracting must confirm the member's data CRC.
unlzx -x good.lzx > extract.log 2>&1
grep -q "crc good" extract.log || fail "unlzx -x did not confirm the data CRC: $(cat extract.log)"
echo "ok   unlzx -x reported 'crc good' (data CRC verified)"

# 3. the extracted bytes must match the payload exactly.
[ -f "$MEMBER" ] || fail "unlzx -x did not produce $MEMBER"
n=0
while IFS= read -r line; do
    n=$((n + 1))
    [ "$line" = "$EXPECTED_LINE" ] || fail "$MEMBER line $n is '$line', expected '$EXPECTED_LINE'"
done < "$MEMBER"
[ "$n" -eq 1 ] || fail "$MEMBER should hold exactly 1 line, got $n"
echo "ok   extracted payload round-tripped byte for byte"

# 4. an archive with a bad header CRC must be refused for that reason, not
#    silently accepted.  The "|| ..." keeps the non-zero status from aborting
#    the script so the refusal itself can be asserted.
if unlzx -v bad.lzx > corrupt.log 2>&1; then
    fail "unlzx accepted an archive with a corrupted header CRC"
fi
grep -q "CRC: Archive_Header" corrupt.log \
    || fail "unlzx refused the corrupt archive for the wrong reason: $(cat corrupt.log)"
echo "ok   corrupted header CRC refused with 'CRC: Archive_Header'"

echo "all unlzx CLI checks passed"
